// Formata qualquer evento recebido em /webhook/notificar como mensagem HTML do Telegram.
// Origens: Grafana Alerting, Diun, Radarr/Sonarr (Arr) e genérico ({titulo, mensagem, gravidade, app}).
const body = ($input.first().json || {}).body || {};
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const emoji = g => {
  g = String(g || '').toLowerCase();
  if (['critical', 'critico', 'crítico', 'erro', 'error', 'falha'].includes(g)) return '🔴';
  if (['warning', 'aviso'].includes(g)) return '🟠';
  if (['ok', 'sucesso', 'success', 'resolved', 'resolvido'].includes(g)) return '🟢';
  return 'ℹ️';
};
let text;
if (Array.isArray(body.alerts)) {
  // Grafana: um bloco por alerta do grupo
  text = body.alerts.map(a => {
    const l = a.labels || {}, an = a.annotations || {};
    const e = a.status === 'resolved' ? '🟢' : emoji(l.severity || 'warning');
    const head = `${e} <b>${esc(l.alertname || 'alerta')}</b>${l.app ? ' — ' + esc(l.app) : ''}${a.status === 'resolved' ? ' (resolvido)' : ''}`;
    return an.summary ? `${head}\n${esc(an.summary)}` : head;
  }).join('\n\n') || `${emoji(body.status)} <b>Alerta do Grafana</b>`;
} else if (body.diun_version) {
  // Diun: imagem nova disponível
  text = `ℹ️ <b>Atualização disponível</b>\n${esc(body.image)} (${esc(body.hostname)})${body.hub_link ? '\n' + esc(body.hub_link) : ''}`;
} else if (body.eventType) {
  // Radarr / Sonarr
  const item = (body.movie && body.movie.title) || (body.series && body.series.title) || '';
  text = `ℹ️ <b>${esc(body.instanceName || 'Arr')}: ${esc(body.eventType)}</b>${item ? '\n' + esc(item) : ''}`;
} else {
  // Genérico (scripts/notify.sh, Home Assistant, Proxmox) ou payload desconhecido
  text = `${emoji(body.gravidade)} <b>${esc(body.titulo || 'Notificação')}</b>${body.app ? ' — ' + esc(body.app) : ''}${body.mensagem ? '\n' + esc(body.mensagem) : ''}`;
}
return [{ json: { text } }];
